-- 0123_rebuild_grade_math_curriculum_v2.sql
-- Destructive rebuild of ordinary PreK-12 Mathematics curriculum only.
-- Preserves education_subjects and ALL PROGRAM_% exam content.
-- Run LOCAL first.

-- Clear attempts/history and question children for ordinary-grade Math.
DELETE FROM education_attempts WHERE id IN (SELECT DISTINCT aa.attempt_id FROM education_attempt_answers aa WHERE aa.question_id IN (SELECT q.id FROM education_questions q JOIN education_subtopics st ON st.id=q.subtopic_id JOIN education_topics t ON t.id=st.topic_id JOIN education_subjects s ON s.id=t.subject_id WHERE s.subject_code='MATH' AND s.grade_code NOT LIKE 'PROGRAM_%'));
DELETE FROM education_mock_attempts WHERE id IN (SELECT DISTINCT maa.attempt_id FROM education_mock_attempt_answers maa WHERE maa.question_id IN (SELECT q.id FROM education_questions q JOIN education_subtopics st ON st.id=q.subtopic_id JOIN education_topics t ON t.id=st.topic_id JOIN education_subjects s ON s.id=t.subject_id WHERE s.subject_code='MATH' AND s.grade_code NOT LIKE 'PROGRAM_%'));
DELETE FROM education_mock_test_questions WHERE question_id IN (SELECT q.id FROM education_questions q JOIN education_subtopics st ON st.id=q.subtopic_id JOIN education_topics t ON t.id=st.topic_id JOIN education_subjects s ON s.id=t.subject_id WHERE s.subject_code='MATH' AND s.grade_code NOT LIKE 'PROGRAM_%');
DELETE FROM education_attempt_answers WHERE question_id IN (SELECT q.id FROM education_questions q JOIN education_subtopics st ON st.id=q.subtopic_id JOIN education_topics t ON t.id=st.topic_id JOIN education_subjects s ON s.id=t.subject_id WHERE s.subject_code='MATH' AND s.grade_code NOT LIKE 'PROGRAM_%');
DELETE FROM education_mock_attempt_answers WHERE question_id IN (SELECT q.id FROM education_questions q JOIN education_subtopics st ON st.id=q.subtopic_id JOIN education_topics t ON t.id=st.topic_id JOIN education_subjects s ON s.id=t.subject_id WHERE s.subject_code='MATH' AND s.grade_code NOT LIKE 'PROGRAM_%');
DELETE FROM education_mock_question_answers WHERE question_id IN (SELECT q.id FROM education_questions q JOIN education_subtopics st ON st.id=q.subtopic_id JOIN education_topics t ON t.id=st.topic_id JOIN education_subjects s ON s.id=t.subject_id WHERE s.subject_code='MATH' AND s.grade_code NOT LIKE 'PROGRAM_%');
DELETE FROM education_student_question_history WHERE question_id IN (SELECT q.id FROM education_questions q JOIN education_subtopics st ON st.id=q.subtopic_id JOIN education_topics t ON t.id=st.topic_id JOIN education_subjects s ON s.id=t.subject_id WHERE s.subject_code='MATH' AND s.grade_code NOT LIKE 'PROGRAM_%');
DELETE FROM education_question_response_details WHERE question_id IN (SELECT q.id FROM education_questions q JOIN education_subtopics st ON st.id=q.subtopic_id JOIN education_topics t ON t.id=st.topic_id JOIN education_subjects s ON s.id=t.subject_id WHERE s.subject_code='MATH' AND s.grade_code NOT LIKE 'PROGRAM_%');
DELETE FROM education_question_metadata WHERE question_id IN (SELECT q.id FROM education_questions q JOIN education_subtopics st ON st.id=q.subtopic_id JOIN education_topics t ON t.id=st.topic_id JOIN education_subjects s ON s.id=t.subject_id WHERE s.subject_code='MATH' AND s.grade_code NOT LIKE 'PROGRAM_%');
DELETE FROM education_questions WHERE id IN (SELECT q.id FROM education_questions q JOIN education_subtopics st ON st.id=q.subtopic_id JOIN education_topics t ON t.id=st.topic_id JOIN education_subjects s ON s.id=t.subject_id WHERE s.subject_code='MATH' AND s.grade_code NOT LIKE 'PROGRAM_%');
DELETE FROM education_subtopics WHERE topic_id IN (SELECT t.id FROM education_topics t JOIN education_subjects s ON s.id=t.subject_id WHERE s.subject_code='MATH' AND s.grade_code NOT LIKE 'PROGRAM_%');
DELETE FROM education_topics WHERE subject_id IN (SELECT s.id FROM education_subjects s WHERE s.subject_code='MATH' AND s.grade_code NOT LIKE 'PROGRAM_%');

