-- Audit: after curriculum-only rebuild, grade_math_questions should be 0.
SELECT s.country_code,s.grade_code,COUNT(DISTINCT t.id) AS topics,COUNT(DISTINCT st.id) AS subtopics,COUNT(DISTINCT q.id) AS questions FROM education_subjects s LEFT JOIN education_topics t ON t.subject_id=s.id LEFT JOIN education_subtopics st ON st.topic_id=t.id LEFT JOIN education_questions q ON q.subtopic_id=st.id AND q.active=1 WHERE s.country_code IN ('US','IN') AND s.subject_code='MATH' AND s.grade_code NOT LIKE 'PROGRAM_%' GROUP BY s.country_code,s.grade_code ORDER BY s.country_code,CASE s.grade_code WHEN 'PREK' THEN 0 WHEN 'K' THEN 1 ELSE CAST(REPLACE(s.grade_code,'GRADE_','') AS INTEGER)+1 END;
SELECT (SELECT COUNT(*) FROM education_questions q JOIN education_subtopics st ON st.id=q.subtopic_id JOIN education_topics t ON t.id=st.topic_id JOIN education_subjects s ON s.id=t.subject_id WHERE s.subject_code='MATH' AND s.grade_code NOT LIKE 'PROGRAM_%') AS grade_math_questions,(SELECT COUNT(*) FROM education_questions q JOIN education_subtopics st ON st.id=q.subtopic_id JOIN education_topics t ON t.id=st.topic_id JOIN education_subjects s ON s.id=t.subject_id WHERE s.grade_code LIKE 'PROGRAM_%') AS program_questions;
