INSERT INTO education_subtopics (topic_id,subtopic_code,subtopic_name,enabled,sort_order) SELECT t.id,'DISTRIBUTIONS','Probability Distributions',1,20 FROM education_topics t JOIN education_subjects s ON s.id=t.subject_id WHERE s.country_code IN ('US','IN') AND s.grade_code='GRADE_12' AND s.subject_code='MATH' AND t.topic_code='STATISTICS_PROBABILITY' AND NOT EXISTS (SELECT 1 FROM education_subtopics st WHERE st.topic_id=t.id AND st.subtopic_code='DISTRIBUTIONS');
INSERT INTO education_subtopics (topic_id,subtopic_code,subtopic_name,enabled,sort_order) SELECT t.id,'INFERENCE','Statistical Inference Foundations',1,30 FROM education_topics t JOIN education_subjects s ON s.id=t.subject_id WHERE s.country_code IN ('US','IN') AND s.grade_code='GRADE_12' AND s.subject_code='MATH' AND t.topic_code='STATISTICS_PROBABILITY' AND NOT EXISTS (SELECT 1 FROM education_subtopics st WHERE st.topic_id=t.id AND st.subtopic_code='INFERENCE');
